for idx,(name,f,e,sample,purity)in enumerate(INVENTORY):
 fraction=AW[e]*atoms(f)[e]/mass(f);pure=sample*purity/100;component=pure*fraction;target=component/2;needed=target/(fraction*purity/100);aw=', '.join(f'{x}={AW[x]}'for x in atoms(f));inp=dict(name=name,formula=f,element=e,sample=sample,purity=purity,pureMass=pure,elementFraction=fraction,componentMass=component,targetComponentMass=target,requiredSampleMass=needed,variant='PURE_COMPOUND_INERT_REST_INVENTORY')
 pre=f'কাল্পনিকগাণিতিকনমুনা{name}:মোট{sample}gএ{f}ভরভাগ{purity}%,বাকিনিষ্ক্রিয়ও{e}মুক্ত।Ar:{aw}।এটি বাস্তবখাদ্য/সার/ব্লিচমাত্রাবাপ্রস্তুতিরনির্দেশনয়।'
